use vstd::prelude::*;

verus! {

/// Given an integer x in [1,3000], returns a vector of exactly four characters:
///   if x < 1200, returns ['A','B','C','\n'],
///   otherwise returns ['A','R','C','\n'].
fn solve(x: i32) -> (result: Vec<char>)
    requires
        1 <= x && x <= 3000,
    ensures
        // exactly four characters
        result.len() == 4,
        // first and third and fourth are always 'A','C','\n' at positions 0,2,3
        result[0] == 'A',
        result[2] == 'C',
        result[3] == '\n',
        // second character depends on x
        result[1] == if x < 1200 { 'B' } else { 'R' },
{
    let mut result: Vec<char> = Vec::new();
    // push 'A'
    result.push('A');
    // push either 'B' or 'R'
    if x < 1200 {
        result.push('B');
    } else {
        result.push('R');
    }
    // push 'C'
    result.push('C');
    // push newline
    result.push('\n');
    result
}

} // end verus! 

fn main() {
    // Example usage (not verified):
    let v1 = solve( 100 );
    assert!(v1 == vec!['A','B','C','\n']);
    let v2 = solve(2000);
    assert!(v2 == vec!['A','R','C','\n']);
}